#!/usr/bin/env python3
"""Render tables from retained measurements. Run after all benchmarks finish."""
import json,pathlib,statistics
r=pathlib.Path.cwd();out=r/'results/microcodec';load=lambda n:json.loads((out/n).read_text());sizes={x['name']:x for x in load('sizes.json')};lines=[]
def add(s=''):lines.append(s)
def table(headers,rows):
 add('| '+' | '.join(headers)+' |');add('| '+' | '.join(['---']*len(headers))+' |')
 for row in rows:add('| '+' | '.join(map(str,row))+' |')
 add()
def num(x):return f'{x:,.0f}'
def ms(x):return f'{x:.2f}'
def mib(x):return f'{x/1048576:.2f}'
add('# Demuxe microcodec PoC — 2026-09-28\n')
add('**Decision: do not build production microcodec loading/routing yet. Prioritize qualifying the minimized common/adaptation builds.** Packet-only AC-3/E-AC-3 is technically successful, but most transfer savings come from pruning FFmpeg and applying LTO/size optimization. Decomposition adds multiple instances, copies and a handoff contract for only a small additional compressed saving. No production files, routing, Player API, native-video/mpv strategy, MSE architecture, or asynchronous bridge infrastructure were changed.\n')
add('This is a bounded synthetic research result, not a browser playback qualification. TrueHD/MLP was deferred: the main comparison does not justify expanding the codec matrix. No object-audio/Atmos preservation is claimed. Existing mpv fallback remains necessary for unsupported representations.\n')
add('## Artifacts and reproduction\n')
add('Build recipes, C ABIs, Node/browser Workers, fixture generator, runtime audit, and benchmark runners are in [`experiments/microcodec`](experiments/microcodec/README.md). External `.wasm` and glue files are in `build/microcodec/<profile>-<optimization>/module.{wasm,mjs}`. Raw measurements are in [`results/microcodec`](results/microcodec/). No SINGLE_FILE build, production cache, loader, package manifest, or asset installation was added.\n')
add('## Sizes\n')
add('Bytes, not KiB. gzip level 9 and Brotli quality 11 compress **each external asset independently**; combined columns sum Wasm + JS. These are runtime module assets, not package/deployment totals. Reference-only test adapters are excluded from path totals.\n')
rows=[]
for name in ['current-adaptation','current-remux','adaptation-Oz','remux-Oz','ac3-Oz','ac3-Os','ac3-O2','dts-Oz','flac-Oz','libflac-Oz']:
 s=sizes[name];rows.append([name,num(s['wasm']['raw']),num(s['glue']['raw']),num(s['wasm']['gzip']),num(s['wasm']['brotli']),num(s['wasm']['gzip']+s['glue']['gzip']),num(s['wasm']['brotli']+s['glue']['brotli'])])
table(['Component','Raw Wasm','Raw JS','Wasm gzip','Wasm Brotli','Combined gzip','Combined Brotli'],rows)
b=sizes['adaptation-Oz'];c=[sizes[n] for n in ['remux-Oz','ac3-Oz','flac-Oz']];cl=[sizes[n] for n in ['remux-Oz','ac3-Oz','libflac-Oz']]
for label,parts in [('FFmpeg FLAC',c),('direct libFLAC (size model; not the composition run)',cl)]:
 delta=b['wasm']['raw']-sum(x['wasm']['raw'] for x in parts);br=b['wasm']['brotli']+b['glue']['brotli']-sum(x['wasm']['brotli']+x['glue']['brotli'] for x in parts)
 add(f'Decomposition with {label} saves {num(delta)} raw Wasm bytes and {num(br)} combined Brotli bytes versus minimized adaptation.\n')
add('The baseline also changes optimization/LTO and allocator settings relative to the installed engine. Thus A→B measures the practical minimized build, not the causal effect of component removal alone. B→C uses matched `-Oz` + LTO and the same common components. No claim that all A→B savings are architectural is warranted.\n')
add('## Codec timing and memory\n')
add('Node Workers, arm64 macOS, Node '+load('ac3-Oz.json')['node']+'. Each row: one worker/fixture startup, then median of 12 complete 3.008-second decode loops. Compile is `WebAssembly.compile`; instantiate is synchronous `new WebAssembly.Instance`; factory includes glue initialization; init opens the decoder. Inputs are already packetized and resident. Times are local-process observations, not network, cold-browser distributions, or playback CPU. Node CPU includes context recreation and process/V8 activity; wall throughput includes packet copies/drain calls, excludes collected PCM copies in timed loops. Peak is maximum Wasm linear-memory capacity, not live allocator use or total JS/Worker/RSS.\n')
rows=[]
for name in ['ac3-Oz','ac3-Os','ac3-O2','dts-Oz']:
 for x in load(name+'.json')['results']:
  duration=x['pcmBytes']/4/x['channels']/48000;median=statistics.median(x['times']);cpu=(x['benchCpu']['user']+x['benchCpu']['system'])/1000/12
  rows.append([name,x['fixture'],ms(x['compileMs']),ms(x['instantiateMs']),ms(x['factoryMs']),ms(x['initMs']),mib(x['initialMemory']),mib(x['peakMemory']),ms(median),f'{duration*1000/median:.1f}×',ms(cpu)])
table(['Build','Fixture','Compile ms','Instantiate ms','Factory ms','Init ms','Initial MiB','Peak MiB','Decode ms','Realtime','CPU ms/clip'],rows)
add('Do not select an optimization solely by binary size. All variants comfortably beat realtime here; warm-process timings vary. `-Oz` is the smallest measured artifact. A larger real-media/browser workload is needed before selecting production optimization. Scratch allocation in the final harness is the largest packet plus padding, not the initial pilot’s unnecessary 1 MiB reserve.\n')
add('## Correctness and reset\n')
add('Fixtures use distinct per-channel tones at 48 kHz: AC-3 stereo, E-AC-3 stereo/5.1, DTS core stereo/5.1. The manifest retains encoder invocation, host FFmpeg version, packet offsets/PTS/durations, stream metadata and SHA256. All frames, including the encoded tail padding, are retained; this is not a gapless source-duration claim.\n')
rows=[]
for x in load('correctness.json'):
 rows.append([x['name'],x['fixture'],x['frames'],x['samples'],hex(x['layout']),x['exact'],all(y['exact'] for y in x['reset']),all(y['recoveryExact'] for y in x['bad'])])
table(['Build','Fixture','Frames','Samples/channel','Layout mask','Exact PCM','Both resets exact','Bad-input recovery exact'],rows)
add('Reference: identical packet ABI linked against the installed adaptation build’s **hash-verified** libavcodec/libswresample/libavutil archives, with its original `-O2`, SIMD and pthread configuration. Every microdecoder frame’s nine metadata fields and interleaved float PCM match exactly. Independent host FFmpeg float comparison uses a predeclared maximum absolute error of `1e-5` (observed errors below `5e-8`), not a tolerance chosen after the result.\n')
add('Output is FFmpeg `AV_SAMPLE_FMT_FLTP` (8), 48,000 Hz. Stereo mask 0x3 is FL/FR; 5.1-side mask 0x60f is FL/FR/FC/LFE/SL/SR, and planes retain that native order. AC-3/E-AC-3 emits 1536 samples (32 ms) per frame; DTS emits 512 (10⅔ ms). PTS is the input packet PTS in a 1/48000 time base. `AVFrame.duration` is zero for this ABI because packet duration is not supplied; consumers must compute frame duration from sample count/rate. Decoder delay and initial-padding fields are zero; this does not assert zero transform/encoder latency.\n')
add('NULL-packet EOF flush returns no additional frames and receive reaches AVERROR_EOF. Both `avcodec_flush_buffers()` and recreate/reset replay exactly. Recreate plus a 480000-sample discontinuity shifts first PTS to 10 seconds while preserving PCM. Truncating the first packet to seven bytes and replacing a full packet with 0xff return invalid-data on send; receive then has no frame; recreate followed by valid packets recovers byte-exactly. These are two deterministic malformed-input cases, not a fuzzing/security qualification or a claim that every payload bit error is rejected.\n')
add('The pinned AC-3 implementation has an explicit flush callback that clears frame state and reseeds dithering. Context recreation is **not required by these tested reset cases**. The browser PoC conservatively uses recreation. FFmpeg documents buffer reset in its [utility API](https://www.ffmpeg.org/doxygen/7.1/group__lavc__misc.html); the local pinned source and tests, rather than that generic promise, establish the result here.\n')
add('## No asynchronous codec runtime\n')
add('`runtime-audit.json` retains final import names, minified glue mappings, memory declarations, and artifact hashes. All four standalone module families have private non-shared memory, no pthread imports, no JSPI/Suspending/promising or Asyncify instrumentation, and `FILESYSTEM=0`. FFmpeg codec builds disable avformat, swresample, avfilter and all thread backends; only libavcodec/libavutil are linked. Link settings use emmalloc, SUPPORT_LONGJMP=0, SIMD enabled, LTO, 256 KiB stack and a 2 MiB initial heap.\n')
add('Some libc syscall imports survive dead-code elimination (`openat`, fd read/seek/write, timer/environment/clock stubs). They do **not** imply filesystem emulation or asynchronous source I/O. Glue has no FS initialization. Instrumented complete test runs call only environment initialization and, where needed, memory growth; no source reads, filesystem calls or timer suspensions are observed. The async JS factory loads/compiles the module; packet decoding itself is synchronous. Existing remux/adaptation retain shared-memory pthread/source-worker behavior.\n')
add('## FLAC encoders\n')
add('Narrow FFmpeg FLAC and direct libFLAC 1.4.3 were measured at compression levels 0 and 5, stereo and six channels, signed 24-bit integer input. All eight round trips are exact. libFLAC receives right-justified integers; FFmpeg S32 input is left-justified. Float-to-FLAC composition explicitly rounds/clips to 24 bits: it is not lossless preservation of arbitrary float PCM. libFLAC’s callback-based [stream encoder API](https://www.xiph.org/flac/api/group__flac__stream__encoder.html) needs no file I/O.\n')
rows=[]
for x in load('encoders.json'):
 rows.append([x['name'],x['channels'],x['level'],x['block'],f"{x['realtime']:.1f}×",ms(x['ms']),mib(x['initialMemory']),mib(x['peakMemory']),x['roundtripExact']])
table(['Encoder','Channels','Level','Block samples','Realtime','200 blocks ms','Heap after open MiB','Peak MiB','Exact roundtrip'],rows)
add('Encoder runs reuse a module across configurations; the after-open heap can retain previous high-water capacity. Both modules declare a 2 MiB initial heap. FFmpeg FLAC allocates/grows substantially during encoder open; direct libFLAC stays smaller. Throughput covers different default block sizes and copied encoded output, so it is a practical configuration comparison, not equal-block algorithm attribution. No AAC or Opus encoder was added.\n')
add('## Minimized common remux\n')
add('Same `native/remux/remux.c`, no redesign. Enabled demuxers: MOV/MP4, Matroska/WebM, MPEG-TS. Outputs: MP4/WebM. Parsers: H.264, HEVC, VP8, VP9, AV1, AAC, MPEG audio, Opus, Vorbis, FLAC, AC-3 (covers E-AC-3). Explicit BSFs: aac_adtstoasc and extract_extradata. Configure also selects required internal dependencies, including vp9_superframe. H.264/HEVC internal parsing remains available for timestamp/configuration logic. Actual enabled components are retained in config_components.h and the build manifests.\n')
add('`extract_extradata` was demonstrated necessary: the first narrow build failed TS opening with “Missing AVC configuration”; adding it restores configuration discovery. Packet-copy AC-3 in the audio-only Matroska control fails MP4 header writing with -28 in **both** installed and minimized bridges; no new AC-3 copy admission is claimed. The AC-3 parser remains an MP4 muxer dependency.\n')
if (out/'remux-correctness.json').exists():
 rows=[]
 for x in load('remux-correctness.json'):rows.append([x['name'],x.get('error') or 'build/open/process complete',', '.join(f"{k}: {'exact' if v['exact'] else 'DIFF'}" for k,v in x.get('streams',{}).items())])
 table(['Fixture','Result','Decoded source/output comparison'],rows)
add('MP4/AAC priming/sample-count behavior is separately controlled against the installed bridge; do not call an existing mismatch a new minimization regression. The suite does not qualify the entire admission matrix, seeking, HEVC/AV1 edge cases, source cancellation, playback output, or MSE lifecycle. Retain the existing engine until those gates pass.\n')
add('## Actual repair experiment and path comparison\n')
add('All three arms produce byte-identical decoded PCM for the 3.008-second AC-3 stereo fixture, 144384 samples/channel. A/B read AC-3-in-Matroska with the unchanged source bridge and encode FLAC24 level 0. C receives pre-extracted packet boundaries, decodes and encodes in Wasm, buffers a minimal Matroska handoff, then runs unchanged remux. That handoff is intentionally fixture-scoped: original-container packet extraction and streaming backpressure are **not implemented or benchmarked** for C. This is an executed component-composition comparison, not an end-to-end production per-file route claim.\n')
remux=load('remux.json');by={x['name']:x for x in remux['results']};comp=load('composition.json');rows=[]
for title,key,parts in [('Current adaptation','current-adaptation',['current-adaptation']),('Minimized adaptation','minimized-adaptation',['adaptation-Oz']),('Remux + AC3 + FFmpeg FLAC','decomposed-remux',['remux-Oz','ac3-Oz','flac-Oz'])]:
 x=by[key];decomposed=len(parts)>1;compressed=sum(sizes[n]['wasm']['brotli']+sizes[n]['glue']['brotli'] for n in parts);initial=x['initialMemory']+(sum(t['initialMemory'] for t in comp['timings']) if decomposed else 0);peak=x['peakMemory']+(comp['peakMemory'] if decomposed else 0);compile=x['compileMs']+(sum(t['compileMs'] for t in comp['timings']) if decomposed else 0);inst=x['instantiateMs']+(sum(t['instantiateMs'] for t in comp['timings']) if decomposed else 0);init=x['openMs']+x['startMs']+(comp['initMs'] if decomposed else 0)
 rows.append([title,' + '.join(parts),num(compressed),mib(initial),mib(peak),ms(compile)+' / '+ms(inst)+' / '+ms(init),ms(x['processMs']+(comp['pipelineMs'] if decomposed else 0)), 'Not isolated'])
table(['Path','Wasm loaded','Brotli bytes incl glue','Initial MiB','Peak MiB*','Compile / instantiate / init ms','Processing wall ms','Decode CPU'],rows)
add('*C memory is the sum of component high-water capacities, a conservative simultaneous-residency model; the PoC closes codec Worker before remux. It excludes JS PCM arrays, packet storage, Matroska staging, source shared buffer, compiled code and browser RSS. Peak is not a total-process claim. Decode CPU for A/B cannot be isolated from encode/demux/mux without instrumentation inside the existing bridge; their table value is processing wall time, **not decode CPU**. C’s decoder/encoder wall measurements and Node process CPU are retained separately in JSON; no fabricated CPU attribution is supplied.\n')
add(f"Chrome: {remux['browser']}. C decoder/PCM-conversion wall time {ms(comp['decodeMs'])} ms, FLAC/copy wall time {ms(comp['encodeMs'])} ms, no clipping. Browser compile/instantiate results are single local observations with possible engine cache effects; not cold-network or statistically stable startup claims.\n")
add('## Provenance and limits\n')
add('FFmpeg lock: `n9.0.2`, archive SHA256 `6e374ed621e48faa40639307dff48ba6fe574a509977956d2cce9669b7cc27e9`. Emscripten `4.0.14`; recipe verifies the version and resolves the installed SDK symlink. All current `patches/ffmpeg-adaptation/*.patch` are applied to an isolated archive extraction and hashed in each provenance manifest. No FFmpeg codec source was modified. libFLAC 1.4.3 archive SHA256 `6c58e69cd22348f441b861092b825e591d0b822e106de6eb0ee4d05d27205b70`, fetched from downloads.xiph.org, pinned by the recipe.\n')
add('Per-build `provenance.json` includes configure/link commands, effective configuration hashes/CFLAGS, bridge hash, resolved SDK path, output hash and invocation duration. Build logs and full generated configs remain beside the outputs. The first pilot omitted explicit --optflags; affected objects were cleaned and rebuilt, and `pilot-config.mak` retains that evidence. Final common profiles were reconfigured with the complete BSF list. Size/runtime audits identify the measured binaries by SHA256. `provenance.json` in results records host identity and source/harness hashes.\n')
add('DTS uses only the FFmpeg DCA decoder registration, with core_only enabled; stock DCA still contains extension-support code, so this is a core-decoding PoC, not a hand-pruned core-only source fork. DTS-HD/objects are not qualified. TrueHD/MLP build selection is available in the recipe but was not built/tested; complete access-unit handling, major-sync recovery, seeks and object metadata remain unresolved.\n')
add('Synthetic tones, three-second clips, 48 kHz only, and bounded malformed inputs establish a narrow correctness result. There is no long-run leak soak, broad bitstream conformance corpus, arbitrary channel-layout conversion, production scheduling, sustained playback CPU or cold-start distribution. These limits are reasons to withhold integration readiness, not to change fallback policy.\n')
add('## Recommendation\n')
add('Proceed with a separate qualification task for the minimized common/adaptation builds. Do not add loadCodec(), cache ownership, lazy codec Workers, route changes or asset-loader APIs based on this result. The packet ABI is simple and the decoder itself is dramatically smaller/lower-memory, but the complete repair path still loads the shared remux engine and a FLAC encoder. Its incremental saving is only tens to low hundreds of KiB compressed while introducing packet extraction, copies, buffering, timestamp and lifecycle contracts. On the requested decision rule, decomposition is probably not worthwhile now.\n')
table(['Component','Builds','Correct','No pthread','No JSPI/Asyncify','Size compelling','Ready for integration'],[
['AC-3/E-AC-3','Yes, Oz/Os/O2','Exact tested PCM','Yes','Yes','Alone yes; composed no','No'],
['DTS','Yes','Exact tested core PCM','Yes','Yes','Alone yes; composed unproven','No'],
['TrueHD/MLP','Not attempted','Unqualified','Unverified','Unverified','Unknown','No'],
['FLAC encoder','Both','Exact integer round trips','Yes','Yes','libFLAC smaller','No'],
['Minimized common remux','Yes','Bounded fixtures; full gates pending','N/A','existing bridge','Yes','No; qualification next']])
(r/'MICROCODEC-POC.md').write_text('\n'.join(lines)+'\n')
